import warnings

import numpy as np
import pandas as pd
from sklearn.base import TransformerMixin


def _get_mask(X, value):
    """Compute a boolean mask for missing-like values."""
    if value == "NaN" or value is None or (isinstance(value, float) and np.isnan(value)):
        return pd.isnull(X)
    return X == value


class NumericalTransformer(TransformerMixin):
    """Provides a small set of common numerical transforms."""

    SUPPORTED_FUNCTIONS = ["log", "log1p"]

    def __init__(self, func):
        warnings.warn(
            """
            NumericalTransformer will be deprecated in 3.0 version.
            Please use sklearn.base.TransformerMixin to write
            custom transformers.
            """,
            DeprecationWarning,
            stacklevel=2,
        )
        assert func in self.SUPPORTED_FUNCTIONS, (
            "Only following func are supported: %s" % self.SUPPORTED_FUNCTIONS
        )
        super().__init__()
        self.__func = func

    def fit(self, X, y=None):
        return self

    def transform(self, X, y=None):
        values, restore = self._coerce_numeric(X)
        self._validate_domain(values)

        if self.__func == "log":
            transformed = np.log(values)
        elif self.__func == "log1p":
            transformed = np.log1p(values)
        else:
            raise ValueError("Invalid function name: %s" % self.__func)

        return restore(transformed)

    def _coerce_numeric(self, X):
        if isinstance(X, pd.DataFrame):
            numeric = X.apply(pd.to_numeric, errors="raise")
            return (
                numeric.to_numpy(dtype=float, copy=False),
                lambda arr: pd.DataFrame(arr, index=X.index, columns=X.columns),
            )

        if isinstance(X, pd.Series):
            numeric = pd.to_numeric(X, errors="raise")
            return (
                numeric.to_numpy(dtype=float, copy=False),
                lambda arr: pd.Series(arr, index=X.index, name=X.name),
            )

        try:
            values = np.asarray(X, dtype=float)
        except (TypeError, ValueError) as exc:
            raise TypeError("NumericalTransformer expects numeric input.") from exc
        return values, lambda arr: arr

    def _validate_domain(self, values):
        mask = ~np.isnan(values)
        if self.__func == "log":
            invalid = values[mask] <= 0
            if np.any(invalid):
                raise ValueError("NumericalTransformer('log') requires all non-null values to be > 0.")
        elif self.__func == "log1p":
            invalid = values[mask] <= -1
            if np.any(invalid):
                raise ValueError(
                    "NumericalTransformer('log1p') requires all non-null values to be > -1."
                )


__all__ = ["NumericalTransformer", "_get_mask"]

import contextlib
from datetime import datetime

import numpy as np
import pandas as pd
from scipy import sparse
from sklearn.base import BaseEstimator, TransformerMixin

from . import logger
from .cross_validation import DataWrapper
from .pipeline import TransformerPipeline, _call_fit, make_transformer_pipeline


string_types = text_type = str


def _handle_feature(fea):
    """Convert 1-D arrays or series to 2-D column vectors."""
    if len(fea.shape) == 1:
        fea = np.array([fea]).T
    return fea


def _build_transformer(transformers):
    if isinstance(transformers, list):
        transformers = make_transformer_pipeline(*transformers)
    return transformers


def _build_feature(columns, transformers, options=None, X=None):
    if options is None:
        options = {}
    if X is None:
        return (columns, _build_transformer(transformers), options)
    return (
        columns(X) if callable(columns) else columns,
        _build_transformer(transformers),
        options,
    )


def _elapsed_secs(t1):
    return (datetime.now() - t1).total_seconds()


def _get_feature_names(estimator):
    """Attempt to extract feature names from a fitted estimator."""
    if hasattr(estimator, "classes_"):
        return estimator.classes_

    getter = getattr(estimator, "get_feature_names", None)
    if callable(getter):
        try:
            return getter()
        except TypeError:
            return None

    getter_out = getattr(estimator, "get_feature_names_out", None)
    if callable(getter_out):
        try:
            return getter_out()
        except TypeError:
            return None
    return None


@contextlib.contextmanager
def add_column_names_to_exception(column_names):
    try:
        yield
    except Exception as ex:
        if ex.args:
            msg = "{}: {}".format(column_names, ex.args[0])
        else:
            msg = text_type(column_names)
        ex.args = (msg,) + ex.args[1:]
        raise


def _is_list_like_columns(columns):
    return isinstance(columns, (list, pd.Index, np.ndarray))


class DataFrameMapper(BaseEstimator, TransformerMixin):
    """Map dataframe column subsets to their own sklearn transformations."""

    def __init__(self, features, default=False, sparse=False, df_out=False, input_df=False, drop_cols=None):
        self.features = features
        self.default = default
        self.built_default = None
        self.sparse = sparse
        self.df_out = df_out
        self.input_df = input_df
        self.drop_cols = [] if drop_cols is None else drop_cols
        self.transformed_names_ = []
        if df_out and (sparse or default):
            raise ValueError("Can not use df_out with sparse or default")

    def _build(self, X=None):
        """Build ``built_features`` and ``built_default``."""
        if self.features is None:
            self.built_features = []
        elif isinstance(self.features, list):
            self.built_features = [_build_feature(*feature, X=X) for feature in self.features]
        else:
            self.built_features = [_build_feature(*self.features, X=X)]
        self.built_default = _build_transformer(self.default)

    @property
    def _selected_columns(self):
        """Return a set of explicitly selected columns."""
        selected_columns = set()
        features = getattr(self, "built_features", None)
        if features is None:
            if self.features is None:
                return selected_columns
            features = self.features if isinstance(self.features, list) else [self.features]

        for feature in features:
            columns = feature[0]
            if _is_list_like_columns(columns):
                selected_columns = selected_columns.union(set(columns))
            else:
                selected_columns.add(columns)
        return selected_columns

    def _unselected_columns(self, X):
        """Return dataframe columns not explicitly selected or dropped."""
        if hasattr(X, "columns"):
            X_columns = list(X.columns)
        elif isinstance(X, np.ndarray):
            X_columns = list(range(X.shape[1]))
        else:
            return []

        return [
            column
            for column in X_columns
            if column not in self._selected_columns and column not in self.drop_cols
        ]

    def __setstate__(self, state):
        super().__setstate__(state)
        raw_features = state.get("features")
        if raw_features is None:
            self.features = None
        elif isinstance(raw_features, list):
            self.features = [_build_feature(*feat) for feat in raw_features]
        else:
            self.features = _build_feature(*raw_features)
        self.sparse = state.get("sparse", False)
        self.default = state.get("default", False)
        self.df_out = state.get("df_out", False)
        self.input_df = state.get("input_df", False)
        self.drop_cols = state.get("drop_cols", [])
        self.built_features = state.get("built_features", getattr(self, "built_features", self.features))
        self.built_default = state.get("built_default", self.default)
        self.transformed_names_ = state.get("transformed_names_", [])

    def __getstate__(self):
        state = super().__getstate__()
        state["features"] = self.features
        state["sparse"] = self.sparse
        state["default"] = self.default
        state["df_out"] = self.df_out
        state["input_df"] = self.input_df
        state["drop_cols"] = self.drop_cols
        state["built_features"] = getattr(self, "built_features", None)
        state["built_default"] = self.built_default
        state["transformed_names_"] = self.transformed_names_
        return state

    def _get_col_subset(self, X, cols, input_df=False):
        """Get a subset of columns from the given table ``X``."""
        if callable(cols):
            cols = cols(X)

        if isinstance(cols, string_types):
            return_vector = True
            cols = [cols]
        else:
            return_vector = False

        if isinstance(X, list):
            X = [x[cols] for x in X]
            X = pd.DataFrame(X)
        elif isinstance(X, DataWrapper):
            X = X.df

        if isinstance(X, np.ndarray):
            if return_vector:
                t = X[:, cols[0]]
            else:
                t = X[:, cols]
            return t if input_df else t

        if return_vector:
            t = X[cols[0]]
        else:
            t = X[cols]

        return t if input_df else t.values

    def fit(self, X, y=None):
        """Fit the configured transformations."""
        self._build(X=X)

        for columns, transformers, options in self.built_features:
            t1 = datetime.now()
            input_df = options.get("input_df", self.input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    Xt = self._get_col_subset(X, columns, input_df)
                    _call_fit(transformers.fit, Xt, y)
            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

        if self.built_default:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:

            if unsel_cols:
                with add_column_names_to_exception(unsel_cols):
                    Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                    _call_fit(self.built_default.fit, Xt, y)
        return self

    def get_names(self, columns, transformer, x, alias=None, prefix="", suffix=""):
        """Return verbose names for the transformed columns."""
        if alias is not None:
            name = alias
        elif _is_list_like_columns(columns):
            name = "_".join(map(str, columns))
        else:
            name = columns

        num_cols = x.shape[1] if len(x.shape) > 1 else 1
        output = []

        if num_cols > 1:
            if isinstance(transformer, TransformerPipeline):
                inverse_steps = transformer.steps[::-1]
                estimators = (estimator for _, estimator in inverse_steps)
                names_steps = (_get_feature_names(estimator) for estimator in estimators)
                names = next((names for names in names_steps if names is not None), None)
            else:
                names = _get_feature_names(transformer)

            if names is not None and len(names) == num_cols:
                output = ["{}_{}".format(name, out_name) for out_name in names]
            else:
                output = ["{}_{}".format(name, idx) for idx in range(num_cols)]
        else:
            output = [name]

        if prefix == suffix == "":
            return output
        return ["{}{}{}".format(prefix, col_name, suffix) for col_name in output]

    def get_dtypes(self, extracted):
        dtypes_features = [self.get_dtype(extracted_feature) for extracted_feature in extracted]
        return [dtype for dtype_feature in dtypes_features for dtype in dtype_feature]

    def get_dtype(self, extracted_feature):
        if isinstance(extracted_feature, np.ndarray) or sparse.issparse(extracted_feature):
            width = extracted_feature.shape[1] if len(extracted_feature.shape) > 1 else 1
            return [extracted_feature.dtype] * width
        if isinstance(extracted_feature, pd.DataFrame):
            return list(extracted_feature.dtypes)
        if isinstance(extracted_feature, pd.Series):
            return [extracted_feature.dtype]
        raise TypeError(type(extracted_feature))

    def _transform(self, X, y=None, do_fit=False):
        """Transform ``X`` and optionally fit first."""
        if do_fit:
            self._build(X=X)

        extracted = []
        transformed_names_ = []

        for columns, transformers, options in self.built_features:
            input_df = options.get("input_df", self.input_df)
            Xt = self._get_col_subset(X, columns, input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    if do_fit and hasattr(transformers, "fit_transform"):
                        t1 = datetime.now()
                        Xt = _call_fit(transformers.fit_transform, Xt, y)
                        logger.info("[FIT_TRANSFORM] %s: %s secs", columns, _elapsed_secs(t1))
                    else:
                        if do_fit:
                            t1 = datetime.now()
                            _call_fit(transformers.fit, Xt, y)
                            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

                        t1 = datetime.now()
                        Xt = transformers.transform(Xt)
                        logger.info("[TRANSFORM] %s: %s secs", columns, _elapsed_secs(t1))

            extracted.append(_handle_feature(Xt))
            alias = options.get("alias")
            prefix = options.get("prefix", "")
            suffix = options.get("suffix", "")
            transformed_names_ += self.get_names(columns, transformers, Xt, alias, prefix, suffix)

        if self.built_default is not False:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:
                Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                if self.built_default is not None:
                    with add_column_names_to_exception(unsel_cols):
                        if do_fit and hasattr(self.built_default, "fit_transform"):
                            Xt = _call_fit(self.built_default.fit_transform, Xt, y)
                        else:
                            if do_fit:
                                _call_fit(self.built_default.fit, Xt, y)
                            Xt = self.built_default.transform(Xt)
                    transformed_names_ += self.get_names(unsel_cols, self.built_default, Xt)
                else:
                    transformed_names_ += unsel_cols

                extracted.append(_handle_feature(Xt))

        self.transformed_names_ = transformed_names_

        if not extracted:
            stacked = np.empty((len(X), 0))
        elif any(sparse.issparse(feature) for feature in extracted):
            stacked = sparse.hstack(extracted).tocsr()
            if not self.sparse:
                stacked = stacked.toarray()
        else:
            stacked = np.hstack(extracted)

        if not self.df_out:
            return stacked

        no_rows_dropped = len(X) == len(stacked)
        index = X.index if no_rows_dropped and hasattr(X, "index") else None

        dtypes = self.get_dtypes(extracted) if extracted else []
        df_out = pd.DataFrame(stacked, columns=self.transformed_names_, index=index)
        for column, dtype in zip(self.transformed_names_, dtypes):
            df_out[column] = df_out[column].astype(dtype)
        return df_out

    def transform(self, X):
        return self._transform(X)

    def fit_transform(self, X, y=None):
        return self._transform(X, y, True)


__all__ = [
    "DataFrameMapper",
    "_handle_feature",
    "_build_transformer",
    "_build_feature",
    "_elapsed_secs",
    "_get_feature_names",
